class ShellPage extends StatefulWidget {const ShellPage({super.key});@override State<ShellPage> createState()=>_ShellState();}
class _ShellState extends State<ShellPage>{
 final catalog=LiveCatalog();List<MediaItem> items=[];Set<String> favorites={};List<String> errors=[];bool loading=true;int tab=0;String filter='Todos';
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{
  final p=await SharedPreferences.getInstance();final cached=await catalog.cached();if(!mounted)return;setState((){favorites=(p.getStringList('favorites')??[]).toSet();items=cached;loading=cached.isEmpty;});await _refresh();
 }
 Future<void> _refresh()async{try{final r=await catalog.refresh();if(!mounted)return;setState((){if(r.items.isNotEmpty)items=r.items;errors=r.errors;loading=false;});}catch(_){if(mounted)setState((){loading=false;errors=['Conexão'];});}}
 Future<void> _favorite(MediaItem item)async{setState((){favorites.contains(item.id)?favorites.remove(item.id):favorites.add(item.id);});final p=await SharedPreferences.getInstance();await p.setStringList('favorites',favorites.toList());}
