  final visible=items.where((i)=>filter=='Todos'||i.typeLabel==filter).toList();
  return Scaffold(appBar:AppBar(title:const Text('CINESHOW',style:TextStyle(color:Color(0xFFE50914),fontWeight:FontWeight.w900,letterSpacing:2)),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>SearchPage(catalog:catalog,onOpen:_details))),icon:const Icon(Icons.search),tooltip:'Buscar')]),body:IndexedStack(index:tab,children:[RefreshIndicator(onRefresh:_refresh,child:CustomScrollView(slivers:[SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[for(final type in ['Todos','Filme','Série','Novela','Reality'])Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(type),selected:filter==type,onSelected:(_)=>setState(()=>filter=type)))])))),if(errors.isNotEmpty)SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(16),child:Text('Algumas fontes não responderam. Exibindo o catálogo salvo.',style:TextStyle(color:Theme.of(context).colorScheme.onSurfaceVariant)))),if(loading)const SliverFillRemaining(child:Center(child:CircularProgressIndicator()))else if(visible.isEmpty)const SliverFillRemaining(child:Center(child:Text('Nenhum título nesta categoria.')))
  else ...[SliverToBoxAdapter(child:HeroCard(item:visible.first,onOpen:()=>_details(visible.first))),const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.fromLTRB(16,20,16,12),child:Text('Explore o catálogo',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)))),SliverPadding(padding:const EdgeInsets.fromLTRB(16,0,16,24),sliver:SliverGrid(delegate:SliverChildBuilderDelegate((context,index)=>PosterCard(item:visible[index],onOpen:()=>_details(visible[index])),childCount:visible.length),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:180,childAspectRatio:.58,crossAxisSpacing:12,mainAxisSpacing:16)))]])),ListView(padding:const EdgeInsets.all(16),children:[const Text('Minha lista',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),if(!items.any((i)=>favorites.contains(i.id)))const Padding(padding:EdgeInsets.only(top:24),child:Text('Adicione títulos à sua lista na tela de detalhes.')),for(final i in items.where((i)=>favorites.contains(i.id)))ListTile(title:Text(i.title),subtitle:Text(i.typeLabel),trailing:const Icon(Icons.chevron_right),onTap:()=>_details(i))]),const SettingsPage()]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Início'),NavigationDestination(icon:Icon(Icons.bookmark_border),label:'Minha lista'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Sobre')]));
 }
}
