class DetailsPage extends StatefulWidget{
 const DetailsPage({super.key,required this.item,required this.catalog,required this.isFavorite,required this.onFavorite});final MediaItem item;final LiveCatalog catalog;final bool isFavorite;final VoidCallback onFavorite;@override State<DetailsPage> createState()=>_DetailsState();
