class _DetailsState extends State<DetailsPage>{
 late bool favorite=widget.isFavorite;late MediaSource selected=widget.item.sources.first;List<Map<String,dynamic>> episodes=[];bool loading=false;String? error;
 @override void initState(){super.initState();if(widget.item.kind!='movie')_episodes();}
 Future<void> _episodes()async{setState((){loading=true;error=null;episodes=[];});try{final e=await widget.catalog.episodes(selected);if(mounted)setState(()=>episodes=e);}catch(_){if(mounted)setState(()=>error='Não foi possível carregar os capítulos. Você pode abrir a fonte original.');}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> _open(String url)async{final uri=Uri.tryParse(url);if(uri==null||uri.scheme!='https')return;try{if(!await launchUrl(uri,mode:LaunchMode.externalApplication)&&mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Não foi possível abrir este endereço.')));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Não foi possível abrir este endereço.')));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.item.title)),body:ListView(padding:const EdgeInsets.all(20),children:[SizedBox(height:260,child:Center(child:SizedBox(width:180,child:Cover(item:widget.item)))),const SizedBox(height:20),Text(widget.item.title,style:const TextStyle(fontSize:28,fontWeight:FontWeight.w800)),Text('${widget.item.typeLabel}${widget.item.year>0?' · ${widget.item.year}':''}',style:const TextStyle(color:Colors.white60)),const SizedBox(height:16),Wrap(spacing:8,children:[for(final s in widget.item.sources)ChoiceChip(label:Text(s.label),selected:s==selected,onSelected:loading?null:(_){setState(()=>selected=s);if(widget.item.kind!='movie')_episodes();})]),const SizedBox(height:12),FilledButton.icon(onPressed:()=>_open(selected.pageUrl),icon:const Icon(Icons.open_in_new),label:const Text('Abrir na fonte')),OutlinedButton.icon(onPressed:(){widget.onFavorite();setState(()=>favorite=!favorite);},icon:Icon(favorite?Icons.bookmark:Icons.bookmark_border),label:Text(favorite?'Na minha lista':'Adicionar à minha lista')),if(widget.item.description.isNotEmpty)Text(widget.item.description),if(widget.item.kind!='movie')... [const SizedBox(height:20),Row(children:[const Expanded(child:Text('Capítulos e episódios',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold))),IconButton(onPressed:loading?null:_episodes,icon:const Icon(Icons.refresh))]),if(loading)const Center(child:Padding(padding:EdgeInsets.all(20),child:CircularProgressIndicator())),if(error!=null)Text(error!,style:const TextStyle(color:Colors.white60)),if(!loading&&error==null&&episodes.isEmpty)const Text('Consulte a lista completa na fonte original.'),for(final e in episodes)ListTile(contentPadding:EdgeInsets.zero,title:Text(e['title'] as String),trailing:const Icon(Icons.open_in_new),onTap:()=>_open((e['page_url'] as String?)??selected.pageUrl))]]));
}
class SearchPage extends StatefulWidget{
 const SearchPage({super.key,required this.catalog,required this.onOpen});final LiveCatalog catalog;final void Function(MediaItem) onOpen;@override State<SearchPage> createState()=>_SearchState();
}
class _SearchState extends State<SearchPage>{Timer? timer;int request=0;List<MediaItem> items=[];bool loading=false;String? error;
 void _query(String q){timer?.cancel();final generation=++request;if(q.trim().length<2){setState((){items=[];loading=false;error=null;});return;}timer=Timer(const Duration(milliseconds:400),()async{if(!mounted)return;setState((){loading=true;error=null;});try{final r=await widget.catalog.refresh(query:q.trim());if(mounted&&generation==request)setState((){items=r.items;loading=false;if(r.errors.isNotEmpty)error='Algumas fontes não responderam.';});}catch(_){if(mounted&&generation==request)setState((){loading=false;error='Não foi possível buscar agora.';});}});}
 @override void dispose(){timer?.cancel();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Buscar')),body:Column(children:[Padding(padding:const EdgeInsets.all(16),child:TextField(autofocus:true,onChanged:_query,decoration:const InputDecoration(hintText:'Filmes, séries e novelas',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))),if(loading)const LinearProgressIndicator(),if(error!=null)Padding(padding:const EdgeInsets.all(12),child:Text(error!)),Expanded(child:ListView.builder(itemCount:items.length,itemBuilder:(_,i)=>ListTile(title:Text(items[i].title),subtitle:Text('${items[i].typeLabel} · ${items[i].sources.length} fonte(s)'),onTap:()=>widget.onOpen(items[i]))))]));
}
class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsState();}
class _SettingsState extends State<SettingsPage>{String version='';String message='';bool checking=false;
 @override void initState(){super.initState();PackageInfo.fromPlatform().then((p){if(mounted)setState(()=>version='${p.version} (${p.buildNumber})');}).catchError((Object _){});}
 Future<void> _updates()async{setState((){checking=true;message='';});final client=http.Client();try{final r=await client.get(Uri.parse('https://api.github.com/repos/bichocutela/CINESHOW/releases/latest'),headers:{'Accept':'application/vnd.github+json'}).timeout(const Duration(seconds:15));if(r.statusCode!=200)throw StateError('Sem release');final j=jsonDecode(r.body) as Map;final current=await PackageInfo.fromPlatform();final tag=(j['tag_name'] as String).replaceFirst(RegExp(r'^v'),'');final nums=tag.split('.').map((n)=>int.tryParse(n)??0).toList();final installed=current.version.split('.').map((n)=>int.tryParse(n)??0).toList();bool newer=false;for(var i=0;i<3;i++){final a=i<nums.length?nums[i]:0,b=i<installed.length?installed[i]:0;if(a!=b){newer=a>b;break;}}if(!mounted)return;setState(()=>message=newer?'Nova versão disponível: $tag':'Você está na versão mais recente publicada.');if(newer){final url=j['html_url'] as String;await launchUrl(Uri.parse(url),mode:LaunchMode.externalApplication);}}catch(_){if(mounted)setState(()=>message='Não foi possível consultar as atualizações agora.');}finally{client.close();if(mounted)setState(()=>checking=false);}}
 @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(24),children:[const Text('CINESHOW',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900)),Text('Versão $version'),const SizedBox(height:24),const Text('Catálogo de filmes, séries e novelas. Puxe o início para atualizar. Os vídeos abrem na fonte original.'),const SizedBox(height:24),FilledButton.icon(onPressed:checking?null:_updates,icon:const Icon(Icons.system_update),label:Text(checking?'Consultando...':'Verificar atualização')),if(message.isNotEmpty)Padding(padding:const EdgeInsets.only(top:16),child:Text(message))]);
}
